-----------------------------
---- WORKSPACE ↔ MONITOR ----
-----------------------------

-- Split workspaces between the laptop panel and the external display:
--   1-5 -> laptop (eDP-1)
--   6-10 -> external (HDMI-A-1), only while it is connected
--
-- When HDMI is disconnected Hyprland moves 6-10 back to the laptop on its
-- own, and a workspace whose monitor is missing gets created on the focused
-- monitor instead, so all 1-10 stay usable on the laptop alone.

local laptopOutput   = "eDP-1"
local externalOutput = "HDMI-A-1"

local laptopWorkspaces   = { 1, 2, 3, 4, 5 }
local externalWorkspaces = { 6, 7, 8, 9, 10 }

for _, id in ipairs(laptopWorkspaces) do
    hl.workspace_rule({ workspace = tostring(id), monitor = laptopOutput })
end

for _, id in ipairs(externalWorkspaces) do
    hl.workspace_rule({ workspace = tostring(id), monitor = externalOutput })
end

-- Workspace each monitor starts on
hl.workspace_rule({ workspace = tostring(laptopWorkspaces[1]),   monitor = laptopOutput,   default = true })
hl.workspace_rule({ workspace = tostring(externalWorkspaces[1]), monitor = externalOutput, default = true })

-- Put existing workspaces on their configured output. Mostly relevant when
-- HDMI is (re)connected while 6-10 already exist on the laptop.
local function moveExistingWorkspaces(ids, output)
    if not hl.get_monitor(output) then
        return
    end

    for _, id in ipairs(ids) do
        if hl.get_workspace(tostring(id)) then
            hl.dispatch(hl.dsp.workspace.move({ workspace = tostring(id), monitor = output }))
        end
    end
end

local function syncWorkspaceMonitors()
    moveExistingWorkspaces(laptopWorkspaces, laptopOutput)
    moveExistingWorkspaces(externalWorkspaces, externalOutput)
end

hl.on("monitor.added", syncWorkspaceMonitors)
hl.on("hyprland.start", syncWorkspaceMonitors)


