-- i3-style bindings, based on the i3 default config.
-- mainMod stays SUPER (Windows key) instead of i3's default Alt.
local mainMod = "SUPER"

-- i3 core bindings ---------------------------------------------------------

-- Start a terminal / application launcher
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + D",      hl.dsp.exec_cmd(menu))

-- Close the focused window
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.close())

-- Focus: j/k/l/semicolon (i3's home-row layout), plus the arrow keys
hl.bind(mainMod .. " + J",         hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + K",         hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + L",         hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + semicolon", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + left",      hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + down",      hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + up",        hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + right",     hl.dsp.focus({ direction = "right" }))

-- Move the focused window: Shift + j/k/l/semicolon, or Shift + arrows
hl.bind(mainMod .. " + SHIFT + J",         hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + K",         hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + L",         hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + semicolon", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + left",      hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + down",      hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + up",        hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + right",     hl.dsp.window.move({ direction = "right" }))

-- Split direction. Hyprland's dwindle layout has no fixed i3-style
-- horizontal/vertical containers; preselect decides where the next window
-- opens instead (right = horizontal split, below = vertical split).
hl.bind(mainMod .. " + H", hl.dsp.layout("preselect right"))
hl.bind(mainMod .. " + V", hl.dsp.layout("preselect down"))

-- Toggle split orientation (i3's "layout toggle split")
hl.bind(mainMod .. " + E", hl.dsp.layout("togglesplit"))

-- Fullscreen and floating
hl.bind(mainMod .. " + F",             hl.dsp.window.fullscreen({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.window.float({ action = "toggle" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Reload config (i3: $mod+Shift+c)
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.reload_config())

-- Exit prompt (i3: $mod+Shift+e), reusing the existing power menu
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/power-menu"))

-- Lock screen. mainMod+L is focus up and mainMod+Shift+L is move up in i3,
-- so use mainMod+Escape (which i3 leaves free) instead.
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("pidof hyprlock >/dev/null 2>&1 || hyprlock"))

-- Screenshot with Flameshot
hl.bind("Print", hl.dsp.exec_cmd("flameshot gui"))

-- Clipboard history (cliphist watchers are started in the autostart block)
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/clipboard-menu"))

-- Resize mode (i3: $mod+r). Enter with mainMod+r, leave with Return/Escape
-- or mainMod+r.
local resizeStep = 10

hl.define_submap("resize", function()
    hl.bind("J",         hl.dsp.window.resize({ x = -resizeStep, y = 0,           relative = true })) -- shrink width
    hl.bind("K",         hl.dsp.window.resize({ x = 0,           y = resizeStep,  relative = true })) -- grow height
    hl.bind("L",         hl.dsp.window.resize({ x = 0,           y = -resizeStep, relative = true })) -- shrink height
    hl.bind("semicolon", hl.dsp.window.resize({ x = resizeStep,  y = 0,           relative = true })) -- grow width

    hl.bind("left",  hl.dsp.window.resize({ x = -resizeStep, y = 0,           relative = true }))
    hl.bind("down",  hl.dsp.window.resize({ x = 0,           y = resizeStep,  relative = true }))
    hl.bind("up",    hl.dsp.window.resize({ x = 0,           y = -resizeStep, relative = true }))
    hl.bind("right", hl.dsp.window.resize({ x = resizeStep,  y = 0,           relative = true }))

    hl.bind("Return",        hl.dsp.submap("reset"))
    hl.bind("Escape",        hl.dsp.submap("reset"))
    hl.bind(mainMod .. " + R", hl.dsp.submap("reset"))
end)

hl.bind(mainMod .. " + R", hl.dsp.submap("resize"))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- i3 bindings with no sane Hyprland/dwindle equivalent are intentionally left
-- unbound instead of being mapped to something misleading:
--   mainMod+S (stacking), mainMod+W (tabbed), mainMod+A (focus parent),
--   mainMod+space (focus tiling/floating mode), mainMod+Shift+R (restart).
-- Hyprland cannot restart in place without ending the session.

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })

-- Brightness keys: hyprsunset gamma (external monitor + laptop screen, perceived brightness)
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("hyprctl hyprsunset gamma +5"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("hyprctl hyprsunset gamma -5"), { locked = true, repeating = true })
hl.bind(mainMod .. " + B",       hl.dsp.exec_cmd("hyprctl hyprsunset reset gamma")) -- reset to config value

-- Original laptop backlight control, kept on a modifier combo
hl.bind(mainMod .. " + XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"), { locked = true, repeating = true })
hl.bind(mainMod .. " + XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


